{"cards": [{"node_code": "N_2a0adadd8e5a40ec", "definition": "针对中国境内具体铁路线路（如京沪、青藏等）的经济概况、建设背景、运营效益及沿线经济影响的研究。", "boundary": "本节点聚焦于“具体线路”的经济属性。边界在于区分“线路经济”与“工程技术”：侧重线路的造价、投资回报、运量预测、对沿线GDP贡献归入本节点；侧重线路的选线、路基、桥梁隧道结构设计归入铁路工程。若内容涉及多条线路的综合网络规划，侧重宏观布局归入中国铁路建设与发展，侧重单条线路细节归入本节点。", "includes": ["特定铁路线路的建设投资、运营成本及经济效益分析", "铁路线路对沿线区域经济发展的带动作用研究", "主要干线、支线及专用线的经济概况与运营数据"], "excludes": ["铁路线路的纯工程技术、地质勘察及施工方法", "不涉及具体线路的宏观铁路网规划理论"], "sibling_distinctions": [{"other_code": "N_fa32e14cb2162f63", "rule": "区分依据为“微观线路”与“宏观建设”：侧重单条或少数几条具体线路的经济指标、沿线影响归入本节点；侧重全国铁路网布局、大规模建设成就、整体发展规模归入中国铁路建设与发展。"}, {"other_code": "N_787ee44c9bb618d6", "rule": "区分依据为“特定对象”与“通用机制”：侧重某条具体线路的运价执行情况、成本构成归入本节点；侧重中国铁路通用的运价体系、成本核算方法、票价政策归入中国铁路运输成本、运价与票价。"}], "cross_boundary_rule": "若内容涉及“某线路开通对区域经济的影响”，主挂载本节点；若涉及“该线路的技术创新”，需关联铁路工程节点，但经济影响部分仍归本节点。"}, {"node_code": "N_d8f6f2de073050b9", "definition": "研究中国地方铁路（非国铁干线）、城际铁路及区域铁路网的经济特征、管理体制、投融资模式及对地方经济贡献的分支。", "boundary": "本节点聚焦于“地方”属性，即行政区域或特定区域范围内的铁路运输经济。边界在于区分“地方铁路”与“国铁干线”：侧重省级、市级铁路，城际铁路，以及地方铁路公司的运营、融资、政企关系归入本节点；侧重国家干线铁路的宏观政策归入方针政策或建设发展。若内容涉及地方铁路与国家铁路的接口经济，侧重地方侧归本节点。", "includes": ["地方铁路、城际铁路的建设投融资模式与经济性分析", "地方铁路管理体制、政企关系及运营效率研究", "区域铁路网对地方产业结构、城镇化发展的经济影响"], "excludes": ["国家干线铁路的宏观战略规划与全国统一定价政策", "纯地方公路、水路等非铁路交通的经济研究"], "sibling_distinctions": [{"other_code": "N_2a0adadd8e5a40ec", "rule": "区分依据为“区域/地方属性”与“具体线路属性”：侧重地方铁路整体特征、区域协调、地方投融资机制归入本节点；侧重某条具体线路（无论是否地方铁路）的详细经济数据与沿线影响归入各线路概况。"}, {"other_code": "N_8224032a29170d9c", "rule": "区分依据为“地域范围”与“企业主体”：侧重地方铁路特有的经济规律、区域政策归入本节点；侧重铁路运输企业（含国铁集团及下属公司）的通用管理、组织架构、人力资源归入铁路运输企业与管理。"}], "cross_boundary_rule": "若内容涉及“某省城际铁路网规划”，主挂载本节点；若涉及“该网中某条具体线路的造价”，可关联各线路概况，但区域整体经济分析归本节点。"}, {"node_code": "N_763ea4ccc0f0ab14", "definition": "研究中国铁路从近代引入到现代发展的历史进程，包括重大事件、政策演变、技术引进及经济制度变迁的学科分支。", "boundary": "本节点聚焦于“历史”维度，即时间轴上的演变过程。边界在于区分“历史”与“现状/理论”：侧重过去发生的铁路事件、历史时期的政策、旧线改造历史、铁路人物事迹归入本节点；侧重当前的经济政策、未来的发展规划归入方针政策或建设发展；侧重抽象的经济规律归入理论。若内容涉及历史线路的经济数据，作为历史背景归入本节点。", "includes": ["中国铁路近代史、革命史及建国后的发展历史", "不同历史时期铁路经济政策、管理体制的演变过程", "中国铁路重大历史事件、人物及历史文献研究"], "excludes": ["当前正在实施的铁路经济政策与改革措施", "未来铁路发展的预测与规划", "纯工程技术的历史演变（如蒸汽机车技术史，除非侧重其经济影响）"], "sibling_distinctions": [{"other_code": "N_ae24be475e947493", "rule": "区分依据为“历史回顾”与“现行政策”：侧重历史上已废止或演变过的政策、方针归入本节点；侧重当前有效、正在执行或未来拟定的方针政策归入方针政策及其阐述。"}, {"other_code": "N_fa32e14cb2162f63", "rule": "区分依据为“时间维度”与“建设成就”：侧重铁路发展的历史脉络、阶段性特征归入本节点；侧重当前及近期的建设规模、新线开通、技术成就归入中国铁路建设与发展。"}], "cross_boundary_rule": "若内容涉及“中国铁路改革史”，主挂载本节点；若涉及“当前铁路改革的具体措施”，主挂载方针政策及其阐述。"}]}
